-- v62 (OPTIONAL). The application applies this automatically and idempotently (dual_ensure_schema). Run v61's migration first (creates reseller_memberships).
-- Adds the wallet-purchase columns. Nothing is updated, dropped or reset; existing membership rows keep NULL (legacy / admin).

SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'reseller_memberships' AND COLUMN_NAME = 'payment_method') = 0, 'ALTER TABLE reseller_memberships ADD COLUMN payment_method VARCHAR(20) DEFAULT NULL', 'SELECT 1'); PREPARE q FROM @s; EXECUTE q; DEALLOCATE PREPARE q;
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'reseller_memberships' AND COLUMN_NAME = 'amount_deducted') = 0, 'ALTER TABLE reseller_memberships ADD COLUMN amount_deducted DECIMAL(12,2) DEFAULT NULL', 'SELECT 1'); PREPARE q FROM @s; EXECUTE q; DEALLOCATE PREPARE q;
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'reseller_memberships' AND COLUMN_NAME = 'wallet_ledger_id') = 0, 'ALTER TABLE reseller_memberships ADD COLUMN wallet_ledger_id BIGINT UNSIGNED DEFAULT NULL', 'SELECT 1'); PREPARE q FROM @s; EXECUTE q; DEALLOCATE PREPARE q;
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'reseller_memberships' AND COLUMN_NAME = 'wallet_ref') = 0, 'ALTER TABLE reseller_memberships ADD COLUMN wallet_ref VARCHAR(60) DEFAULT NULL', 'SELECT 1'); PREPARE q FROM @s; EXECUTE q; DEALLOCATE PREPARE q;
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'reseller_memberships' AND COLUMN_NAME = 'balance_before') = 0, 'ALTER TABLE reseller_memberships ADD COLUMN balance_before DECIMAL(12,2) DEFAULT NULL', 'SELECT 1'); PREPARE q FROM @s; EXECUTE q; DEALLOCATE PREPARE q;
SET @s = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'reseller_memberships' AND COLUMN_NAME = 'balance_after') = 0, 'ALTER TABLE reseller_memberships ADD COLUMN balance_after DECIMAL(12,2) DEFAULT NULL', 'SELECT 1'); PREPARE q FROM @s; EXECUTE q; DEALLOCATE PREPARE q;
